const history = valid.map(item => `Customer: ${item.json.message}\nSupport: ${item.json.ai_response}`).join('\n\n');
return [{ json: { history } }];

// Gemini chat call. Retries temporary errors (503 overloaded, 429, timeouts) with growing waits,
// then tries GEMINI_FALLBACK_MODEL. Only a bad key (401/403) stops immediately.
const PROMPT = `Classify this customer support message.\n\nCategories:\nRefund\nTechnical Issue\nOrder Status\nGeneral Question\n\nMessage:\n${$('Validate Input').item.json.message}\n\nReturn only the category name.`;
const base = $env.GEMINI_BASE_URL || 'https://generativelanguage.googleapis.com/v1beta/openai';
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const statusOf = (e) => Number(e.httpCode || e.statusCode || e.response?.status || 0);
const models = [...new Set([$env.GEMINI_CHAT_MODEL || 'gemini-3.1-flash-lite', $env.GEMINI_FALLBACK_MODEL].filter(Boolean))];
let lastError;
for (const model of models) {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST', url: `${base}/chat/completions`, json: true, timeout: 30000,
        headers: { Authorization: `Bearer ${$env.GEMINI_API_KEY}` },
        body: { model, messages: [{ role: 'user', content: PROMPT }] },
      });
      if (!res?.choices?.[0]?.message?.content) throw new Error('Empty answer from ' + model);
      return { json: res };
    } catch (e) {
      lastError = e;
      if ([401, 403].includes(statusOf(e))) throw e;
      if (attempt < 3) await sleep(attempt * 3000);
    }
  }
}
throw lastError;

