const docs = [
  "Refund Policy: Customers can request a refund within 7 days of purchase if the service has not been used.",
  "Shipping Policy: Orders are processed within 2 business days and delivered within 5-7 business days.",
  "Password Reset: To reset your password go to the login page and click 'Forgot Password'.",
  "Account Deletion: To permanently delete your account contact support or use account settings.",
  "Payment Failure: If payment fails verify card details or try another payment method.",
  "Subscription Cancellation: You can cancel your subscription anytime from the billing section."
];

return docs.map((d, i) => ({ json: { id: i + 1, text: d } }));

// Gemini embedding call (1536 dimensions, matches the Qdrant collection). Retries temporary errors.
// No fallback model: vectors from a different model would not match the stored ones.
const base = $env.GEMINI_BASE_URL || 'https://generativelanguage.googleapis.com/v1beta/openai';
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const statusOf = (e) => Number(e.httpCode || e.statusCode || e.response?.status || 0);
const model = $env.GEMINI_EMBEDDING_MODEL || 'gemini-embedding-001';
const input = $json.text;
let lastError;
for (let attempt = 1; attempt <= 5; attempt++) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: `${base}/embeddings`, json: true, timeout: 30000,
      headers: { Authorization: `Bearer ${$env.GEMINI_API_KEY}` },
      body: { model, dimensions: 1536, input },
    });
    if (!res?.data?.[0]?.embedding) throw new Error('Empty embedding from ' + model);
    return { json: res };
  } catch (e) {
    lastError = e;
    if ([401, 403].includes(statusOf(e))) throw e;
    if (attempt < 5) await sleep(attempt * 2000);
  }
}
throw lastError;

const req = $input.first().json;
const body = req.body || {};
const headers = req.headers || {};
const fail = (status, error) => [{ json: { valid: false, status, error } }];

// Optional shared secret: enforced only when SUPPORT_API_KEY is set in .env
const expectedKey = $env.SUPPORT_API_KEY || '';
if (expectedKey && headers['x-api-key'] !== expectedKey) return fail(401, 'Missing or invalid X-API-Key header');

const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const message = typeof body.message === 'string' ? body.message.trim() : '';
const name = typeof body.name === 'string' ? body.name.trim() : '';

if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail(400, 'A valid "email" is required');
if (!message) return fail(400, '"message" is required');
if (message.length > 2000) return fail(400, '"message" must be 2000 characters or fewer');
if (name.length > 100) return fail(400, '"name" must be 100 characters or fewer');

return [{ json: { valid: true, email, message, name } }];

const q = $input.first().json.query || {};
const ticketId = typeof q.ticket_id === 'string' ? q.ticket_id.trim() : '';
const rating = typeof q.rating === 'string' ? q.rating.trim().toLowerCase() : '';
const feedback = typeof q.feedback === 'string' && q.feedback.trim() ? q.feedback.trim().slice(0, 500) : 'Customer clicked email feedback link';
const fail = (error) => [{ json: { valid: false, status: 400, error } }];

if (!/^SUP-\d{4}-\d{4,}$/.test(ticketId)) return fail('Invalid or missing ticket_id');
if (!['good', 'bad'].includes(rating)) return fail('rating must be "good" or "bad"');

return [{ json: { valid: true, ticket_id: ticketId, rating, feedback } }];

// Builds the failure email. Written defensively: n8n also fires this for crashed/interrupted runs,
// whose data can be incomplete, so every field has a fallback and the email is always readable.
let e = {}; let ticket = {};
try { e = $('Error Trigger').first().json || {}; } catch (err) { /* keep defaults */ }
try { ticket = $input.first().json || {}; } catch (err) { /* keep defaults */ }
const execution = e.execution || {};
const wfName = (e.workflow && e.workflow.name) || 'Customer Support AI';
const failedNode = execution.lastNodeExecuted || 'unknown step';
const reason = (execution.error && execution.error.message) || 'unknown error (the run was probably interrupted)';
const link = execution.url || (execution.id ? 'execution ' + execution.id : 'unknown');
let text = 'Workflow: ' + wfName + '\nFailed step: ' + failedNode + '\nError: ' + reason + '\nExecution: ' + link;
if (ticket.ticket_id) {
  text += '\n\nThe customer has NOT received an answer. Please follow up manually.\nTicket: ' + ticket.ticket_id + '\nCustomer: ' + ticket.customer_email + '\nMessage: ' + ticket.message;
}
return [{ json: {
  smtpFrom: $env.SMTP_FROM || 'support@example.com',
  supportAlertEmail: $env.SUPPORT_ALERT_EMAIL || 'support-team@example.com',
  subject: '[n8n] ' + wfName + ' failed at ' + failedNode,
  text,
} }];

parameters.query:
INSERT INTO support_requests (ticket_id, customer_name, customer_email, message, status, execution_id)
VALUES ($1, $2, $3, $4, 'pending', $5)
RETURNING ticket_id;

UPDATE support_requests SET status = 'failed'
WHERE execution_id = $1 AND status = 'pending'
RETURNING ticket_id, customer_email, left(message, 300) AS message;
